// Diamond-profile ring/disc: ridge (half-thickness 0) at bore & rim,
// full 6mm thickness at mid-radius. Radial faces slope 47deg in Y,
// so arch undersides are 47deg (declared, no >60deg bridge span).
module ring_diamond(r_in, r_out) {
    r_mid = (r_in + r_out) / 2;
    rotate([90,0,0]) rotate_extrude() polygon(points=[
        [r_in,0],[r_mid,3],[r_out,0],[r_mid,-3]]);
}
module disc_diamond(r_out) {
    rotate([90,0,0]) rotate_extrude() polygon(points=[
        [0,-3],[r_out-3.25,-3],[r_out,0],[r_out-3.25,3],[0,3]]);
}
module cyl_y(r, h) rotate([90,0,0]) cylinder(r=r, h=h, center=true);
